// 初始化Layout数据结构并判断其类型
AscendC::Shape<int,int,int> shape = AscendC::MakeShape(10, 20, 30);
AscendC::Stride<int,int,int> stride = AscendC::MakeStride(1, 100, 200);
auto layoutMake = AscendC::MakeLayout(shape, stride);
AscendC::Layout<AscendC::Shape<int, int, int>, AscendC::Stride<int, int, int>> layoutInit(shape, stride);
bool value = AscendC::is_layout<decltype(shape)>::value; //value = false
value = AscendC::is_layout<decltype(stride)>::value; //value = false
value = AscendC::is_layout<decltype(layoutMake)>::value;//value = true
value = AscendC::is_layout<decltype(layoutInit)>::value;//value = true
2.2.5 TensorTrait
2.2.5.1 TensorTrait 简介
TensorTrait数据结构是描述Tensor相关信息的基础模板类，包含Tensor的数据类型、
逻辑位置和Layout内存布局。借助模板元编程技术，该类在编译时完成计算和代码生
成，从而降低运行时开销。
需要包含的头文件
#include "kernel_operator_tensor_trait.h"
原型定义
template <typename T, TPosition pos = TPosition::GM, typename LayoutType = Layout<Shape<>, Stride<>>>
struct TensorTrait {
    using LiteType = T;
    using LiteLayoutType = LayoutType;
    static constexpr const TPosition tPos = pos; // 该常量成员为后续功能扩展做预留
public:
    __aicore__ inline TensorTrait(const LayoutType& t = {});
    __aicore__ inline LayoutType& GetLayout();
    __aicore__ inline const LayoutType& GetLayout() const;
    __aicore__ inline void SetLayout(const LayoutType& t);
};
