SIMT编程场景：
__global__ __launch_bounds__(1024) void KernelSyncThreads(float* dst, int count)
{
     int idx = threadIdx.x;
     if (idx > 0 && idx < count) {
         dst[idx] = 1;
     }

     // 等待block内所有thread都执行到当前代码
     asc_syncthreads();

     if (idx == 0) {
         dst[0] = 0;
         for(int i = 1023; i > 0; i--) {
             dst[0] += dst[i];
         }
     }
}
