// 模板基类
template <typename T>
class BaseTemplate {
public:
    T value;
};
// 模板派生类
template <typename T>
class DerivedTemplate : public BaseTemplate<T> {};
// 检查 Base 是否是 Derived 的基类
AscendC::PRINTF("Is Base a base of Derived? %d\n" , AscendC::Std::is_base_of<Base, Derived>::value);
// 检查 Derived 是否是 Base 的基类（应该为 false）
